typedef enum { EXPR_INT, EXPR_BINARY } ExprKind;
typedef struct Expr { ExprKind kind; Token token; } Expr;   /* common base */
typedef struct { ExprKind kind; Token token; Expr *left, *right; Token op; } BinaryExpr;
static void print_tree(const Expr *e) {                     /* per-node walk */
    switch (e->kind) {
    case EXPR_BINARY: {                                     /* downcast by kind */
        const BinaryExpr *b = (const BinaryExpr *)e;
        putchar('('); print_tree(b->left); print_tree(b->right); putchar(')'); break;
    }
    default: fputs(e->token.text, stdout); break;
    }
}
